def imagej_description_dict(description):
    metadata = imageio.coreetadata getDescription(description)
    result = {}
    for key_value in metadata.split(b'\n'):
        key, value = key_value.split(b'=', 1)
        if key == b'ImageJ':
            result[key.decode()] = value.decode()
        elif key == b'images':
            result[key.decode()] = int(value)
        elif key == b'hyperstack':
